const QI=[[/first ?name|last ?name|^name/,'🙋'],[/mail/,'📧'],[/^(alternate-)?phone|whatsapp|phone number/,'📱'],[/dob|birth|\\bage\\b/,'🎂'],[/gender/,'🧑‍🤝‍🧑'],[/country/,'🌍'],[/state\\b/,'🗺️'],[/city/,'🏙️'],[/zip|postal/,'📮'],[/ethnic/,'🌐'],[/relationship|marital/,'💞'],[/rural|urban/,'🏘️'],[/income|salary|earn/,'💰'],[/children|child|\\bkid/,'👶'],[/educat|degree|school|college|universit/,'🎓'],[/industry|sector|department/,'🏭'],[/employ|\\bjob|occupation|profession/,'💼'],[/company|organi|business/,'🏢'],[/experience|years/,'⏳'],[/decision|budget|spend/,'🧾'],[/alcohol|beer|wine/,'🍷'],[/tobacco|nicotine|smok|vape/,'💨'],[/coffee|\\btea\\b|drink|beverage/,'☕'],[/food|\\beat|meal|restaurant|dining|cuisine|deliver/,'🍽️'],[/\\bcar\\b|vehicle|automobile|driv/,'🚗'],[/motorcycle|scooter|\\bbike/,'🏍️'],[/fuel|petrol|diesel/,'⛽'],[/travel|trip|vacation|holiday|flight|hotel|tour/,'✈️'],[/game|gaming|esport|console/,'🎮'],[/sport|fitness|gym|exercise|workout/,'🏋️'],[/health|doctor|medic|wellness|hospital/,'🩺'],[/beauty|skin|hair|makeup|cosmetic|grooming/,'💄'],[/fashion|cloth|apparel|shoe/,'👗'],[/luxury|premium|jewel|watch/,'💎'],[/\\bpet|\\bdog|\\bcat\\b/,'🐾'],[/home|house|rent|apartment|household/,'🏡'],[/bank|loan|credit|card|insurance|invest|saving|payment|upi|finance/,'💳'],[/smartphone|laptop|computer|device|tablet|\\btv\\b|electronic|gadget/,'💻'],[/social|content|creator|influenc/,'📸'],[/stream|video|music|movie|podcast|media|entertain/,'🎬'],[/shop|buy|purchase|retail|store|online/,'🛍️'],[/survey|reward|panel|research|incentive/,'🎁'],[/language/,'🗣️'],[/hobb|interest/,'🎨'],[/news/,'📰'],[/book|\\bread/,'📚'],[/baby|parent|pregnan/,'🍼'],[/solar|energy|electric/,'⚡'],[/clean|laundry|detergent/,'🧼'],[/internet|app\\b|website|software|digital|tech/,'🌐']];
